mapper.select:
SELECT FROM gw_doc_file df JOIN gw_doc_folder f ON f.folder_id = df.folder_id JOIN gw_attach a ON a.attach_id = df.attach_id LEFT JOIN gw_user u ON u.user_id = df.owner_id WHERE df.deleted_at IS NULL AND df.folder_id = #{folderId}
AND (LOWER(df.title) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(a.file_nm) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(df.description) LIKE LOWER('%' || #{keyword} || '%'))
ORDER BY df.created_at DESC

SELECT FROM gw_doc_file df JOIN gw_doc_folder f ON f.folder_id = df.folder_id JOIN gw_attach a ON a.attach_id = df.attach_id LEFT JOIN gw_user u ON u.user_id = df.owner_id WHERE df.deleted_at IS NULL AND f.deleted_at IS NULL AND
AND (LOWER(df.title) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(a.file_nm) LIKE LOWER('%' || #{keyword} || '%'))
ORDER BY df.created_at DESC LIMIT #{limit}
